import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.D7xI0JV8.js";const p=JSON.parse('{"title":"Why zkde.fi?","description":"","frontmatter":{},"headers":[],"relativePath":"why.md","filePath":"why.md"}'),i={name:"why.md"};function s(l,e,n,h,c,u){return t(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="why-zkde-fi" tabindex="-1">Why zkde.fi? <a class="header-anchor" href="#why-zkde-fi" aria-label="Permalink to &quot;Why zkde.fi?&quot;">​</a></h1><h2 id="the-problem" tabindex="-1">The Problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The Problem&quot;">​</a></h2><p>Many DeFi users face a forced tradeoff:</p><ul><li>full transparency that leaks strategy and timing</li><li>opaque delegation that weakens user assurance and auditability</li></ul><h2 id="why-this-matters" tabindex="-1">Why This Matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why This Matters&quot;">​</a></h2><p>When privacy and trust cannot coexist, users either avoid automation or accept unnecessary risk.</p><h2 id="our-position" tabindex="-1">Our Position <a class="header-anchor" href="#our-position" aria-label="Permalink to &quot;Our Position&quot;">​</a></h2><p>zkde.fi focuses on privacy-aware execution with observable control surfaces:</p><ul><li>user-owned wallet execution</li><li>flow-specific verification behavior</li><li>delegated automation bounded by session constraints</li><li>trust context through profile and passport views</li></ul><h2 id="what-problem-this-solves" tabindex="-1">What Problem This Solves <a class="header-anchor" href="#what-problem-this-solves" aria-label="Permalink to &quot;What Problem This Solves&quot;">​</a></h2><p>It removes the false choice between complete exposure and complete opacity by giving users bounded, inspectable, and route-aware controls.</p><pre class="mermaid" data-mermaid-source="flowchart%20LR%0A%20%20T1%5BFull%20transparency%5D%20--%3E%20X%5BUser%20risk%5D%0A%20%20T2%5BOpaque%20automation%5D%20--%3E%20X%0A%20%20Z%5Bzkde.fi%20approach%5D%20--%3E%20Y%5BPrivacy-aware%20%2B%20observable%20execution%5D%0A%20%20Y%20--%3E%20O%5BBetter%20operational%20trust%5D">flowchart LR
  T1[Full transparency] --&gt; X[User risk]
  T2[Opaque automation] --&gt; X
  Z[zkde.fi approach] --&gt; Y[Privacy-aware + observable execution]
  Y --&gt; O[Better operational trust]</pre><p>Next: <a href="/docs/concepts.html">Concepts</a> | <a href="/docs/quick-start.html">Quick start</a></p>`,13)])])}const m=a(i,[["render",s]]);export{p as __pageData,m as default};
